-- =============================================================================
-- 452 — LE CAHIER D'EXERCICES DE TLE (partie 17)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 452 --niveau Tle --matieres droit-economie,management-sgn --suffixe 17 > supabase/contenu/452_exercices_tle_17.sql
--
-- 96 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   droit-economie.k144     24 exercices · 8 chapitres
--   droit-economie.k145     24 exercices · 8 chapitres
--   management-sgn.k169     24 exercices · 8 chapitres
--   management-sgn.k170     24 exercices · 8 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('a92fa301-4607-5fda-a35d-e59a2badad46'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois achats, trois contrats","competence":"analyser-document","situation":"Léo et Jade, 16 ans, ne sont pas émancipés. Chacun a fait un achat seul, comme la société Bâtir. Le tableau les recense.","documents":[{"id":"achats","type":"tableau","titre":"Les achats de la semaine","source":"Situations imaginées pour l’exercice.","colonnes":["Acheteur","Achat","Prix"],"lignes":[["Léo, 16 ans","Une baguette et un jus","2,80 €"],["Jade, 16 ans","Une moto d’occasion","4 500 €"],["Société Bâtir, majeure","Du ciment pour un chantier","1 200 €"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’achat qu’une lycéenne non émancipée ne peut pas faire seule.","aide":"Pense aux actes courants de la vie d’un adolescent.","type":"zone","document":"achats","multiple":false},{"enonce":"Quelle est la sanction du contrat conclu par Jade seule ?","aide":"L’incapacité protège une personne précise.","type":"choix","options":[{"id":"a","texte":"La clause pénale prévue par le vendeur"},{"id":"b","texte":"La nullité absolue, que n’importe qui peut demander"},{"id":"c","texte":"La résiliation pour l’avenir uniquement"},{"id":"d","texte":"La nullité relative, que ses parents peuvent demander"}],"multiple":false},{"enonce":"Qui peut agir pour obtenir cette annulation ?","aide":"La règle protège Jade, pas le vendeur.","type":"choix","options":[{"id":"a","texte":"Toute personne qui s’intéresse à l’affaire"},{"id":"b","texte":"Le conseil de la société Bâtir, de passage"},{"id":"c","texte":"Les représentants légaux de Jade, donc ses parents"},{"id":"d","texte":"Le vendeur de la moto, qui regrette la vente"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"L’achat d’une **moto à 4 500 €** dépasse un acte courant : Jade est incapable de le conclure seule."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’incapacité protège l’intérêt privé du mineur : c’est une **nullité relative**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Seule la partie protégée agit : ici **les parents de Jade**, ses représentants légaux."}]$ex$::jsonb),
  ('a92fa301-4607-5fda-a35d-e59a2badad46'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le casque qui n’était pas neuf","competence":"analyser-texte","situation":"Nina a commandé un casque de moto en ligne. Elle écrit au site, puis veut connaître ses droits. Le tableau rappelle les trois vices du consentement.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Le message de Nina","source":"Texte écrit pour l’exercice.","blocs":["Le vendeur m’a affirmé que ce casque était neuf et homologué. Je découvre qu’il est d’occasion et non homologué, et il le savait. J’ai reçu le colis le 10 juin. — Nina"]},{"id":"vices","type":"tableau","titre":"Les vices du consentement","colonnes":["Vice","Définition"],"lignes":[["Erreur","Fausse idée que l’on se fait tout seul"],["Dol","Tromperie volontaire pour obtenir l’accord"],["Violence","Contrainte ou menace pour obtenir l’accord"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le vice du consentement dont Nina est victime.","aide":"Le vendeur savait et a affirmé le contraire.","type":"zone","document":"vices","multiple":false},{"enonce":"Pour obtenir l’annulation, que doit établir Nina ?","aide":"Reviens à la définition du dol.","type":"choix","options":[{"id":"a","texte":"Que le vendeur l’a trompée volontairement pour obtenir son accord"},{"id":"b","texte":"Que le contrat a été signé en présence d’un témoin"},{"id":"c","texte":"Que ce casque coûte moins cher chez un autre vendeur"},{"id":"d","texte":"Que le vendeur a déjà été condamné pour escroquerie"}],"multiple":false},{"enonce":"Le délai de rétractation est de 14 jours à compter de la réception du colis. Quel jour de juin se termine-t-il ?","aide":"Ajoute 14 au 10.","type":"nombre","unite":"juin"},{"enonce":"L’action en nullité se prescrit en principe par un nombre d’années fixe. Combien d’années ?","aide":"Regarde la fin de la partie sur la nullité.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0"]},"explication":"Le vendeur l’a trompée volontairement : c’est un **dol**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Il faut prouver la **tromperie volontaire** qui a déterminé son consentement."},{"cle":{"type":"nombre","valeur":24,"tolerance":0},"affichage":"24 juin","explication":"10 + 14 = le **24 juin**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 ans","explication":"En principe, l’action se prescrit par **cinq ans**."}]$ex$::jsonb),
  ('a92fa301-4607-5fda-a35d-e59a2badad46'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le canapé et la clause cachée","competence":"analyser-document","situation":"Amel commande un canapé sur un site. Les conditions générales et le bon de commande ne sont pas tous irréprochables.","documents":[{"id":"cg","type":"tableau","titre":"Extrait des conditions générales","source":"Conditions imaginées pour l’exercice.","colonnes":["Art.","Clause"],"lignes":[["1","Livraison sous quinze jours ouvrés."],["2","Le vendeur peut augmenter le prix après la commande, sans que le client puisse refuser ou annuler."],["3","Le client dispose de 14 jours pour se rétracter."]],"enteteLignes":true},{"id":"bon","type":"fiche","modele":"ticket","entete":"Maison Confort","sousTitre":"Bon de commande à distance","emoji":"🛋️","lignes":[{"texte":"Canapé 3 places","valeur":"900 €"},{"texte":"Livraison","valeur":"60 €"},{"separateur":true},{"texte":"TOTAL","valeur":"960 €","gras":true,"id":"z1"}],"pied":"Acompte de 30 % à la commande","teinte":"bleu"}],"questions":[{"enonce":"Touche la clause qui crée un déséquilibre significatif au détriment d’Amel.","aide":"Une seule clause laisse le vendeur tout décider.","type":"zone","document":"cg","multiple":false},{"enonce":"Que devient cette clause abusive ?","aide":"La sanction vise la clause, pas le contrat entier.","type":"choix","options":[{"id":"a","texte":"Elle devient une clause pénale au profit d’Amel"},{"id":"b","texte":"Elle entraîne la nullité de tout le contrat de vente"},{"id":"c","texte":"Elle est réputée non écrite, le reste du contrat demeure"},{"id":"d","texte":"Elle s’applique sauf si Amel s’y oppose par lettre"}],"multiple":false},{"enonce":"Quel est l’acompte à verser à la commande, en euros ?","aide":"Calcule 30 % du total du bon.","type":"nombre","unite":"€"},{"enonce":"Associe chaque situation à sa sanction ou à son remède.","aide":"Pense à qui la règle protège.","type":"association","gauche":[{"id":"g0","texte":"Consentement obtenu par tromperie"},{"id":"g1","texte":"Objet contraire à l’ordre public"},{"id":"g2","texte":"Clause abusive"},{"id":"g3","texte":"Achat à distance regretté"}],"droite":[{"id":"d0","texte":"Réputée non écrite"},{"id":"d1","texte":"Nullité relative"},{"id":"d2","texte":"Rétractation sous 14 jours"},{"id":"d3","texte":"Nullité absolue"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La clause 2 permet au vendeur de changer le prix sans recours : c’est une **clause abusive**."},{"cle":{"type":"choix","ids":["c"]},"explication":"La clause abusive est **réputée non écrite** : elle disparaît, le contrat subsiste."},{"cle":{"type":"nombre","valeur":288,"tolerance":0},"affichage":"288 €","explication":"30 % de 960 € = 0,3 × 960 = **288 €**."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"Chaque cas a son remède : le **vice du consentement** appelle la nullité relative, l’**ordre public** la nullité absolue, la **clause abusive** sa disparition, le **contrat à distance** la rétractation."}]$ex$::jsonb),
  ('d22a9234-0748-578b-b13c-bd7013d42cab'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"L’ordinateur qui n’arrive pas","competence":"analyser-document","situation":"Théo a commandé un ordinateur à 800 € avec 20 % d’acompte. La date de livraison est passée. Le tableau retrace les faits.","documents":[{"id":"chrono","type":"tableau","titre":"Chronologie","source":"Situation imaginée pour l’exercice.","colonnes":["Date","Événement"],"lignes":[["1er mars","Commande d’un ordinateur à 800 € avec 20 % d’acompte"],["15 mars","Date de livraison promise"],["20 mars","Toujours rien reçu"],["21 mars","Lettre recommandée : « livrez sous huit jours »"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’étape qui est la mise en demeure.","aide":"C’est la lettre recommandée qui somme d’exécuter.","type":"zone","document":"chrono","multiple":false},{"enonce":"Combien de jours de retard le 20 mars, par rapport à la date promise ?","aide":"Compte du 15 au 20 mars.","type":"nombre","unite":"jours"},{"enonce":"Quel est le montant de l’acompte versé, en euros ?","aide":"Calcule 20 % de 800.","type":"nombre","unite":"€"},{"enonce":"Théo veut obtenir l’ordinateur promis, pas un remboursement. Quelle sanction choisit-il ?","aide":"Il veut la chose elle-même.","type":"choix","options":[{"id":"a","texte":"La résolution du contrat de vente"},{"id":"b","texte":"La réduction du prix convenu"},{"id":"c","texte":"L’exécution forcée en nature"},{"id":"d","texte":"La clause résolutoire automatique"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c1"]},"explication":"La lettre du 21 mars somme le vendeur de livrer : c’est la **mise en demeure**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 jours","explication":"20 − 15 = **5 jours** de retard."},{"cle":{"type":"nombre","valeur":160,"tolerance":0},"affichage":"160 €","explication":"0,2 × 800 = **160 €**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Obtenir la prestation promise, c’est l’**exécution forcée en nature**."}]$ex$::jsonb),
  ('d22a9234-0748-578b-b13c-bd7013d42cab'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le plan de travail ébréché","competence":"raisonner","situation":"Clémence a fait poser une cuisine. À la livraison, un coin du plan de travail est ébréché : un défaut mineur. Elle doit choisir une sanction proportionnée.","documents":[{"id":"sanc","type":"tableau","titre":"Les sanctions de l’inexécution","colonnes":["Sanction","Effet"],"lignes":[["Exception d’inexécution","Suspendre sa propre prestation"],["Exécution forcée","Obtenir la prestation promise"],["Réduction du prix","Garder le bien contre un prix diminué"],["Résolution","Anéantir le contrat"]],"enteteLignes":true},{"id":"devis","type":"fiche","modele":"ticket","entete":"Cuisines du Midi","sousTitre":"Devis accepté","emoji":"🍳","lignes":[{"texte":"Cuisine équipée","valeur":"8 000 €"},{"texte":"Pose","valeur":"1 200 €"},{"separateur":true},{"texte":"TOTAL","valeur":"9 200 €","gras":true}],"pied":"Acompte versé : 30 %","teinte":"ambre"}],"questions":[{"enonce":"Quelle sanction est proportionnée à un défaut mineur ?","aide":"Elle veut garder la cuisine.","type":"choix","options":[{"id":"a","texte":"La résolution, en faisant reprendre toute la cuisine"},{"id":"b","texte":"Le refus de payer absolument tout le solde dû"},{"id":"c","texte":"La réduction du prix, en gardant la cuisine"},{"id":"d","texte":"La nullité du contrat pour cause d’incapacité"}],"multiple":false},{"enonce":"Touche la sanction la plus lourde, celle qui anéantit le contrat.","aide":"Cherche le verbe « anéantir ».","type":"zone","document":"sanc","multiple":false},{"enonce":"Elle obtient 10 % de réduction sur le total du devis. Quel prix paie-t-elle, en euros ?","aide":"Calcule 90 % de 9 200.","type":"nombre","unite":"€"},{"enonce":"Elle a versé 30 % d’acompte sur 9 200 €. Combien reste-t-il à payer sur le prix réduit, en euros ?","aide":"Acompte : 0,3 × 9 200. Puis soustrais.","type":"nombre","unite":"€"}]}$ex$::jsonb,
