  ('d22a9234-0748-578b-b13c-bd7013d42cab'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le buffet livré en retard","competence":"raisonner","situation":"Une entreprise commande à un traiteur un buffet pour un séminaire. Le contrat contient plusieurs clauses ; le buffet arrive avec douze jours de retard.","documents":[{"id":"clauses","type":"tableau","titre":"Extrait du contrat","source":"Contrat imaginé pour l’exercice.","colonnes":["Art.","Clause"],"lignes":[["4","Retard de livraison : 150 € par jour de retard."],["7","Le contrat prend fin de plein droit huit jours après une mise en demeure restée sans effet."],["9","Paiement sous trente jours."]],"enteteLignes":true},{"id":"faits","type":"tableau","titre":"Les faits","colonnes":["Donnée","Valeur"],"lignes":[["Retard constaté","12 jours"],["Préjudice réellement subi","600 €"]],"enteteLignes":true}],"questions":[{"enonce":"Quel montant la clause de l’article 4 donne-t-elle pour douze jours de retard, en euros ?","aide":"Multiplie le tarif par le nombre de jours.","type":"nombre","unite":"€"},{"enonce":"Le préjudice réel est de 600 €. Que peut faire le juge ?","aide":"Compare 1 800 € et 600 €.","type":"choix","options":[{"id":"a","texte":"Refuser d’examiner la clause puisqu’elle est signée"},{"id":"b","texte":"Doubler la somme pour punir le traiteur fautif"},{"id":"c","texte":"Réduire la clause pénale, car elle est manifestement excessive"},{"id":"d","texte":"Annuler tout le contrat de traiteur sans autre motif"}],"multiple":false},{"enonce":"Touche la clause résolutoire.","aide":"Elle prévoit la fin automatique du contrat.","type":"zone","document":"clauses","multiple":false},{"enonce":"Associe chaque situation au mécanisme qui convient.","aide":"Distingue « pour l’avenir » de « rétroactivement ».","type":"association","gauche":[{"id":"g0","texte":"Un abonnement arrêté pour l’avenir"},{"id":"g1","texte":"Commande jamais livrée, annulée rétroactivement"},{"id":"g2","texte":"Refus de payer le solde tant que les travaux ne sont pas finis"},{"id":"g3","texte":"Fin automatique après un manquement désigné"}],"droite":[{"id":"d0","texte":"Exception d’inexécution"},{"id":"d1","texte":"Clause résolutoire"},{"id":"d2","texte":"Résolution"},{"id":"d3","texte":"Résiliation"}]}]}$ex$::jsonb,
