  ('f484e499-f3ce-54e3-b956-af5552b7985a'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La rivière de l’Aubelle","competence":"argumenter","situation":"Une cuve de solvants fuit dans l’Aubelle, rivière imaginaire. Poissons morts, berge à restaurer, pêcheur sans revenus : plusieurs acteurs peuvent agir.","documents":[{"id":"art","type":"texte","genre":"article","titre":"Fuite à l’usine de peinture","source":"Article imaginé pour l’exercice","blocs":["Une cuve de solvants s’est vidée dans l’Aubelle. Des milliers de poissons sont morts et le cours d’eau doit être restauré. Un pêcheur professionnel ne peut plus travailler. Le procureur a ouvert une enquête pour pollution."]},{"id":"qui","type":"tableau","titre":"Qui peut agir ?","colonnes":["Acteur","Ce qu’il peut demander"],"lignes":[["Le pêcheur professionnel","Indemnisation de sa perte de revenus"],["Une association de protection de l’environnement","Réparation du préjudice écologique"],["Le procureur","Des poursuites et une sanction pénale"]],"enteteLignes":true}],"questions":[{"enonce":"Touche celui qui agit pour faire prononcer une sanction pénale.","aide":"La société est représentée par le ministère public.","type":"zone","document":"qui","multiple":false},{"enonce":"Comment qualifie-t-on la mort de la faune et la dégradation de la rivière ?","aide":"Aucune personne ne le subit directement.","type":"choix","options":[{"id":"a","texte":"Un simple préjudice moral, subi par le seul pêcheur professionnel"},{"id":"b","texte":"Un préjudice esthétique, réparable par une simple amende"},{"id":"c","texte":"Un préjudice écologique, atteinte aux écosystèmes"},{"id":"d","texte":"Une perte de chance, réparée au profit de l’association"}],"multiple":false},{"enonce":"Range chaque conséquence.","aide":"Réparer ou sanctionner ?","type":"categories","categories":[{"id":"c0","texte":"Responsabilité civile"},{"id":"c1","texte":"Responsabilité pénale"}],"items":[{"id":"i0","texte":"Restaurer le milieu aux frais de l’usine"},{"id":"i1","texte":"Dommages et intérêts au pêcheur"},{"id":"i2","texte":"Amende prononcée contre le dirigeant"},{"id":"i3","texte":"Jugement devant le tribunal correctionnel"}]},{"enonce":"Comment répare-t-on en priorité le préjudice écologique ?","aide":"Pense à ce qui rend la rivière à son état.","type":"choix","options":[{"id":"a","texte":"Par une simple interdiction de pêche"},{"id":"b","texte":"Par une somme versée au dirigeant"},{"id":"c","texte":"En nature, en restaurant le milieu"},{"id":"d","texte":"Par des excuses écrites au maire"}],"multiple":false}]}$ex$::jsonb,
