  ('24986ead-410b-5517-a9ed-e540dad75237'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre dossiers, quatre régimes","competence":"analyser-document","situation":"Un cabinet d’avocats reçoit quatre dossiers. Avant de plaider, il faut qualifier chaque situation : quel régime de responsabilité s’applique ?","documents":[{"id":"dossiers","type":"tableau","titre":"Quatre dossiers","source":"Situations imaginées pour l’exercice.","colonnes":["Dossier","Faits"],"lignes":[["A","Un salarié se blesse en tombant d’un échafaudage pendant son service."],["B","Un scooter renverse un piéton sur un passage protégé."],["C","Un sèche-cheveux neuf surchauffe à cause d’un défaut de fabrication."],["D","Un déménageur casse l’armoire qu’il devait transporter."]],"enteteLignes":true}],"questions":[{"enonce":"Touche le dossier où un véhicule terrestre à moteur est impliqué.","aide":"Cherche le scooter.","type":"zone","document":"dossiers","multiple":false},{"enonce":"Touche le dossier qui relève de la responsabilité du fait des produits défectueux.","aide":"Un produit neuf, un défaut de fabrication.","type":"zone","document":"dossiers","multiple":false},{"enonce":"Range chaque dossier dans son régime.","aide":"Commence par les régimes spéciaux.","type":"categories","categories":[{"id":"c0","texte":"Accident du travail"},{"id":"c1","texte":"Circulation (loi Badinter)"},{"id":"c2","texte":"Produit défectueux"},{"id":"c3","texte":"Responsabilité contractuelle"}],"items":[{"id":"i0","texte":"Dossier C"},{"id":"i1","texte":"Dossier A"},{"id":"i2","texte":"Dossier B"},{"id":"i3","texte":"Dossier D"}]}]}$ex$::jsonb,
