  ('24986ead-410b-5517-a9ed-e540dad75237'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le chêne et la tempête","competence":"raisonner","situation":"Deux arbres sont tombés sur des voitures pendant une tempête. Le tableau compare les deux cas à l’aune de la force majeure.","documents":[{"id":"fm","type":"tableau","titre":"Deux cas de chute d’arbre","source":"Situations imaginées pour l’exercice.","colonnes":["Cas","Événement","Extérieur ?","Imprévisible ?","Irrésistible ?"],"lignes":[["Cas A","Tempête exceptionnelle non annoncée, arbre sain arraché","Oui","Oui","Oui"],["Cas B","Tempête annoncée trois jours avant, arbre mort jamais élagué","Oui","Non","Non"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui montre que l’événement du cas B n’était pas imprévisible.","aide":"Cherche la colonne « Imprévisible ? » dans la ligne du cas B.","type":"zone","document":"fm","multiple":false},{"enonce":"Dans le cas A, que peut obtenir le propriétaire de l’arbre ?","aide":"Les trois critères sont réunis.","type":"choix","options":[{"id":"a","texte":"Une exonération qui ne vaut que devant le juge pénal"},{"id":"b","texte":"Aucune exonération, le gardien répond toujours"},{"id":"c","texte":"Une exonération totale, par la force majeure"},{"id":"d","texte":"Une exonération partielle par la faute de la victime"}],"multiple":false},{"enonce":"Complète la conclusion sur le cas B.","aide":"Une tempête annoncée se prévoit.","type":"trous","segments":["Dans le cas B, la force majeure est ",0," car la tempête était ",1," et l’arbre mal entretenu."],"banque":["prévisible","écartée","retenue","imprévisible"]},{"enonce":"Dans le cas B, le dommage est de 4 000 €. Le juge retient une faute de la victime à 25 % (voiture garée sous un arbre signalé dangereux). Quelle indemnité, en euros ?","aide":"Le responsable paie 75 %.","type":"nombre","unite":"€"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c3"]},"explication":"Dans le cas B, « Imprévisible ? » vaut **Non** : la tempête était annoncée."},{"cle":{"type":"choix","ids":["c"]},"explication":"Extérieur, imprévisible et irrésistible : **force majeure**, exonération totale."},{"cle":{"type":"trous","trous":[["ecartee"],["previsible"]]},"affichage":"écartée · prévisible","explication":"La force majeure est **écartée** car la tempête était **prévisible**."},{"cle":{"type":"nombre","valeur":3000,"tolerance":0},"affichage":"3000 €","explication":"0,75 × 4 000 = **3 000 €** : la faute de la victime exonère partiellement."}]$ex$::jsonb),
  ('24986ead-410b-5517-a9ed-e540dad75237'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La trottinette qui prend feu","competence":"argumenter","situation":"La batterie d’une trottinette neuve s’enflamme dans le garage de Mehdi. Il doit choisir sur quel fondement agir.","documents":[{"id":"faits","type":"texte","genre":"article","titre":"Le sinistre de Mehdi","source":"Texte écrit pour l’exercice","blocs":["Mehdi a acheté une trottinette électrique chez un revendeur. Une semaine plus tard, la batterie s’enflamme : le garage brûle (6 500 €), du matériel est détruit (800 €) et la trottinette est perdue (900 €). Le contrat de vente du revendeur dit : « aucune responsabilité quelle que soit la cause »."]},{"id":"fond","type":"tableau","titre":"Les fondements possibles","colonnes":["Fondement","Contre qui","Ce que Mehdi doit prouver"],"lignes":[["Inexécution du contrat de vente","Le revendeur","Le manquement au contrat"],["Produit défectueux","Le producteur","Le défaut, le dommage et le lien, sans faute"],["Fait personnel","Toute personne fautive","Une faute, le dommage et le lien"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le fondement qui permet d’agir contre le fabricant sans prouver de faute.","aide":"Regarde la dernière colonne.","type":"zone","document":"fond","multiple":false},{"enonce":"Quel est le montant total des dommages de Mehdi, en euros ?","aide":"Additionne garage, matériel et trottinette.","type":"nombre","unite":"€"},{"enonce":"Que vaut la clause « aucune responsabilité quelle que soit la cause » face à un consommateur ?","aide":"Pense aux clauses abusives.","type":"choix","options":[{"id":"a","texte":"Elle supprime aussi la responsabilité du fabricant"},{"id":"b","texte":"Elle est écartée : elle crée un déséquilibre significatif"},{"id":"c","texte":"Elle est valable car Mehdi a signé le contrat"},{"id":"d","texte":"Elle vaut uniquement pour la faute de Mehdi"}],"multiple":false},{"enonce":"Range la démarche de qualification dans l’ordre.","aide":"Du plus spécial au plus général.","type":"ordre","items":[{"id":"a","texte":"Sinon, je cherche un contrat entre les parties"},{"id":"b","texte":"Sinon, j’applique la responsabilité extracontractuelle"},{"id":"c","texte":"Je cherche un régime spécial applicable"}]}]}$ex$::jsonb,
