  ('25aa91ff-0435-5f94-b6d9-abc2e77460af'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les clauses de Romain","competence":"analyser-document","situation":"Romain signe un CDI. Son contrat comporte trois clauses particulières, dont une est irrégulière.","documents":[{"id":"cl","type":"tableau","titre":"Extrait du contrat de Romain","source":"Contrat imaginé pour l’exercice.","colonnes":["Clause","Contenu"],"lignes":[["Mobilité","Le salarié peut être muté à Paris ou dans le reste de l’Île-de-France."],["Non-concurrence","Interdiction de travailler pour un concurrent pendant 5 ans, partout en France, sans aucune contrepartie."],["Télétravail","Deux jours par semaine, si le salarié le souhaite."]],"enteteLignes":true}],"questions":[{"enonce":"Touche la clause qui est irrégulière.","aide":"Une clause qui interdit de travailler doit être compensée.","type":"zone","document":"cl","multiple":false},{"enonce":"Pourquoi cette clause est-elle irrégulière ?","aide":"Relis la fin de la clause.","type":"choix","options":[{"id":"a","texte":"Elle protège un intérêt légitime de l’entreprise"},{"id":"b","texte":"Elle ne prévoit aucune contrepartie financière"},{"id":"c","texte":"Elle a été signée trop tard dans l’année"},{"id":"d","texte":"Elle n’a pas été rédigée en langue anglaise"}],"multiple":false},{"enonce":"Touche la clause dont la zone géographique est définie précisément.","aide":"Cherche une région nommée.","type":"zone","document":"cl","multiple":false},{"enonce":"Range chaque élément d’une clause de non-concurrence.","aide":"Temps, espace, contrepartie, intérêt légitime.","type":"categories","categories":[{"id":"c0","texte":"Condition de validité"},{"id":"c1","texte":"Clause irrégulière"}],"items":[{"id":"i0","texte":"La durée est limitée dans le temps"},{"id":"i1","texte":"Elle protège un intérêt légitime de l’entreprise"},{"id":"i2","texte":"Tous les métiers du monde sont interdits"},{"id":"i3","texte":"Aucune limite de durée n’est prévue"},{"id":"i4","texte":"Une contrepartie financière est prévue"}]}]}$ex$::jsonb,
