  ('25aa91ff-0435-5f94-b6d9-abc2e77460af'::uuid, 3, 3, 15, 50, 3,
   $ex${"titre":"Auto-entrepreneur ou salarié ?","competence":"argumenter","situation":"Yanis est graphiste « auto-entrepreneur » pour une agence. Ses échanges avec son responsable posent la question d’une requalification.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Les messages du responsable","participants":[{"nom":"Responsable","emoji":"🧑‍💼","cote":"gauche"},{"nom":"Yanis","emoji":"🧑‍🎨","cote":"droite"}],"repliques":[{"qui":"Responsable","texte":"Demain, tu es à l’agence à 9 h et tu utilises notre logiciel."},{"qui":"Yanis","texte":"Et si je veux prendre un autre client ?"},{"qui":"Responsable","texte":"Non, sinon je ne te donne plus de missions."}]},{"id":"ind","type":"tableau","titre":"Les indices relevés","source":"Situation imaginée pour l’exercice.","colonnes":["Indice","Constat"],"lignes":[["Horaires","Imposés par l’agence"],["Matériel","Logiciel de l’agence exigé"],["Tarif","Fixé par Yanis lui-même"],["Clientèle","Menace de ne plus donner de missions"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux indices de subordination qui pèsent le plus lourd ici : les horaires et la menace.","aide":"Un ordre et une sanction.","type":"zone","document":"ind","multiple":true},{"enonce":"Qui peut requalifier cette relation en contrat de travail ?","aide":"Le juge regarde les faits.","type":"choix","options":[{"id":"a","texte":"Le notaire qui a rédigé le contrat"},{"id":"b","texte":"Le conseil de prud’hommes, selon les faits"},{"id":"c","texte":"L’agence, par une simple déclaration"},{"id":"d","texte":"Le propriétaire du logiciel utilisé"}],"multiple":false},{"enonce":"Range chaque situation.","aide":"Subordination ou liberté d’organisation ?","type":"categories","categories":[{"id":"c0","texte":"Contrat de travail"},{"id":"c1","texte":"Contrat d’entreprise"}],"items":[{"id":"i0","texte":"Une vendeuse dont l’employeur fixe les horaires"},{"id":"i1","texte":"Un plombier salarié d’une entreprise"},{"id":"i2","texte":"Un plombier artisan appelé par un particulier"},{"id":"i3","texte":"Un graphiste qui organise seul son temps pour plusieurs clients"}]}]}$ex$::jsonb,
