},{"id":"b","texte":"Le doublement de son salaire pour toujours"},{"id":"c","texte":"Une indemnité encadrée par un barème"},{"id":"d","texte":"Une peine de prison pour son employeur"}],"multiple":false}]}$ex$::jsonb,
