   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La **camionnette** est un apport en nature : un bien apporté à la société, et non une somme d’argent."},{"cle":{"type":"nombre","valeur":40000,"tolerance":0},"affichage":"40 000 €","explication":"12 000 + 8 000 + 20 000 = **40 000 €**."},{"cle":{"type":"nombre","valeur":2000,"tolerance":0},"affichage":"2000 €","explication":"Hugo détient 8 000 ÷ 40 000 = 20 % du capital, donc 20 % × 10 000 = **2 000 €**."}]$ex$::jsonb),
  ('07df3dc6-904b-51d9-8ca8-879437ce0777'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un prêt ou une société ?","competence":"argumenter","situation":"Léa veut lancer une pizzeria ambulante. Malik propose de l’aider, mais à ses conditions. Est-ce vraiment un contrat de société ?","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Le message de Malik","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Malik","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"Je lance ma pizzeria ambulante. Tu veux entrer dans l’affaire ?"},{"qui":"Malik","texte":"Je te verse 5 000 € pour développer ton camion, mais je ne veux pas m’en occuper."},{"qui":"Léa","texte":"Et si l’affaire perd de l’argent ?"},{"qui":"Malik","texte":"Tu me rembourses quand même mes 5 000 € : je ne veux rien perdre."}]},{"id":"trois","type":"tableau","titre":"Les trois éléments du contrat de société","source":"Résumé du cours.","colonnes":["Élément","Question à se poser"],"lignes":[["Les apports","Chaque associé met-il quelque chose dans l’entreprise ?"],["L’affectio societatis","Les associés veulent-ils collaborer à l’entreprise commune, sur un pied d’égalité ?"],["Le partage des résultats","Les associés partagent-ils les bénéfices et supportent-ils les pertes ?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui montre que Malik refuse de contribuer aux pertes.","aide":"Cherche ce que Malik exige quoi qu’il arrive.","type":"zone","document":"sms","multiple":false},{"enonce":"Relie chaque phrase de Malik à l’élément du contrat de société qui la concerne.","aide":"Reprends les trois questions du tableau, une par une.","type":"association","gauche":[{"id":"g0","texte":"« Je te verse 5 000 € pour ton camion »"},{"id":"g1","texte":"« Je ne veux pas m’en occuper »"},{"id":"g2","texte":"« Tu me rembourses quand même »"}],"droite":[{"id":"d0","texte":"Pas de contribution aux pertes"},{"id":"d1","texte":"Il y a bien un apport"},{"id":"d2","texte":"Pas d’affectio societatis"}]},{"enonce":"Quelle est la bonne qualification de l’accord proposé par Malik ?","aide":"Compte les éléments du tableau que l’accord respecte.","type":"choix","options":[{"id":"a","texte":"C’est une société : une clause de remboursement garanti est tout à fait permise"},{"id":"b","texte":"Ce n’est pas une société : il manque l’affectio societatis et le partage des pertes"},{"id":"c","texte":"Ce n’est pas une société : un apport en argent est interdit par le Code civil"},{"id":"d","texte":"C’est une société : un apport d’argent suffit à lui seul à former le contrat"}],"multiple":false},{"enonce":"Imaginons une vraie société : Malik apporte 5 000 €, Léa son camion estimé à 15 000 €. Pour 8 000 € de bénéfice, combien revient à Malik ?","aide":"Malik détient 5 000 sur 20 000 du capital.","type":"nombre","unite":"€"}]}$ex$::jsonb,
