tiple":false},{"enonce":"Le franchisé du cas D réalise 240 000 € de chiffre d’affaires dans l’année. Quelle redevance annuelle doit-il verser, en euros ?","aide":"La redevance est un pourcentage du chiffre d’affaires.","type":"nombre","unite":"€"},{"enonce":"Le fabricant du cas C appartient à un groupe dont le chiffre d’affaires mondial atteint 3 milliards d’euros. Quelle amende maximale peut-il encourir, en millions d’euros ?","aide":"Le plafond est de 10 % du chiffre d’affaires mondial.","type":"nombre","unite":"M€"},{"enonce":"Que faut-il retenir du cas B ?","aide":"Compare les cas B et C : qu’est-ce qui change ?","type":"choix","options":[{"id":"a","texte":"Des prix bas pratiqués par une entreprise dominante sont toujours prédateurs"},{"id":"b","texte":"Toute entreprise qui dépasse la moitié du marché est automatiquement sanctionnée"},{"id":"c","texte":"Une position dominante est interdite dès qu’elle dure plus de deux années"},{"id":"d","texte":"Être dominant n’est pas interdit : seul l’abus de cette position l’est"}],"multiple":false}]}$ex$::jsonb,
