[{"id":"a","texte":"A et B ont les mêmes coûts, car elles vendent chacune 10 000 unités par mois"},{"id":"b","texte":"A est pénalisée, car ses gros stocks la rendent vulnérable aux ruptures d’approvisionnement"},{"id":"c","texte":"B est plus sûre que A, car son stock faible la protège de toute rupture d’approvisionnement"},{"id":"d","texte":"B économise du stockage, mais une rupture d’approvisionnement la paralyse très vite"}],"multiple":false}]}$ex$::jsonb,
