droite":[{"id":"d0","texte":"Client"},{"id":"d1","texte":"Atelier"},{"id":"d2","texte":"Service commercial"}]},{"enonce":"Combien d’heures par semaine les ressaisies à la main font-elles perdre ?","aide":"Commandes × ressaisies × minutes, puis convertis en heures.","type":"nombre","unite":"h"},{"enonce":"Que permettrait un workflow sur ce circuit ?","aide":"Un workflow automatise l’enchaînement des tâches.","type":"choix","options":[{"id":"a","texte":"Faire disparaître le client du circuit, puisque la commande serait traitée seule"},{"id":"b","texte":"Remplacer l’atelier par le service commercial pour produire plus vite"},{"id":"c","texte":"Faire passer automatiquement la commande d’un acteur à l’autre, sans la ressaisir"},{"id":"d","texte":"Supprimer le bon de livraison, puisque plus aucune information ne circulerait"}],"multiple":false}]}$ex$::jsonb,
