   $ex${"titre":"Trop d’agences pour un seul fondateur","competence":"raisonner","situation":"Le fondateur de Sourire & Co, réseau imaginaire d’agences d’aide à domicile, supervise lui-même le travail en visitant une agence par jour ouvré, soit 5 par semaine.","documents":[{"id":"frise","type":"frise","titre":"Le réseau grandit","source":"Chiffres imaginés pour l’exercice.","debut":2015,"fin":2025,"pas":1,"evenements":[{"id":"z1","date":2015,"nom":"4 agences"},{"id":"z2","date":2018,"nom":"12 agences"},{"id":"z3","date":2021,"nom":"30 agences"},{"id":"z4","date":2024,"nom":"60 agences"}]},{"id":"report","type":"tableau","titre":"Reporting du mois","source":"Chiffres imaginés pour l’exercice.","colonnes":["Agence","Objectif du mois (€)","Réalisé (€)"],"lignes":[["Nord","50 000","54 000"],["Sud","50 000","41 000"],["Est","50 000","50 000"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la première étape où il ne peut plus visiter toutes les agences en une semaine.","aide":"Il visite 5 agences par semaine.","type":"zone","document":"frise","multiple":false},{"enonce":"En 2024, combien de semaines lui faudrait-il pour visiter les 60 agences ?","aide":"Divise le nombre d’agences par 5.","type":"nombre","unite":"semaines"},{"enonce":"Touche l’agence qui n’a pas atteint son objectif.","aide":"Compare l’objectif et le réalisé de chaque ligne.","type":"zone","document":"report","multiple":false},{"enonce":"Quel pourcentage de son objectif l’agence Sud a-t-elle atteint ?","aide":"Divise 41 000 par 50 000.","type":"nombre","unite":"%"},{"enonce":"Quel mécanisme de coordination ce reporting illustre-t-il ?","aide":"Le tableau fixe un objectif et compare le résultat obtenu.","type":"choix","options":[{"id":"a","texte":"L’ajustement mutuel : les agences se mettent d’accord en se parlant librement"},{"id":"b","texte":"La standardisation des résultats : chaque agence a un objectif, sans méthode imposée"},{"id":"c","texte":"La supervision directe : le fondateur contrôle chaque geste de chaque agence"},{"id":"d","texte":"La standardisation des qualifications : tous les salariés ont suivi la même formation"}],"multiple":false}]}$ex$::jsonb,
