  ('68a546b8-1543-5849-875a-2e2933b8756b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre annonces, quatre styles","competence":"analyser-document","situation":"Le directeur d’une usine imaginaire doit changer le planning d’été. Chaque jour de la semaine, il s’y prend autrement. Jeudi, les salariés votent.","documents":[{"id":"annonces","type":"tableau","titre":"Les annonces du directeur","source":"Annonces imaginées pour l’exercice.","colonnes":["Jour","Annonce"],"lignes":[["Lundi","« Le planning d’été change dès le 1er juillet : c’est décidé, inutile d’en discuter. »"],["Mardi","« Je déciderai seul du planning, mais donnez-moi d’abord votre avis par écrit. »"],["Mercredi","« Nous choisissons ensemble le planning : chaque équipe vote jeudi. »"],["Jeudi","« Je fixe le planning seul, mais j’ai prévu un goûter pour que tout le monde se sente bien. »"]],"enteteLignes":true},{"id":"vote","type":"tableau","titre":"Résultat du vote de jeudi (24 salariés)","source":"Chiffres imaginés pour l’exercice.","colonnes":["Planning","Voix"],"lignes":[["Planning A (2 équipes de 8 h)",9],["Planning B (3 équipes de 8 h)",15]],"enteteLignes":true}],"questions":[{"enonce":"Associe chaque jour au style de direction.","aide":"Qui décide ? Est-ce que l’on consulte ? Se soucie-t-on du bien-être ?","type":"association","gauche":[{"id":"g0","texte":"Lundi"},{"id":"g1","texte":"Mardi"},{"id":"g2","texte":"Mercredi"},{"id":"g3","texte":"Jeudi"}],"droite":[{"id":"d0","texte":"Consultatif"},{"id":"d1","texte":"Paternaliste"},{"id":"d2","texte":"Autoritaire"},{"id":"d3","texte":"Participatif"}]},{"enonce":"Touche l’annonce où les salariés décident avec le directeur.","aide":"Cherche le mot « ensemble » et le vote.","type":"zone","document":"annonces","multiple":false},{"enonce":"Quel pourcentage des 24 salariés a voté pour le planning B ?","aide":"Divise 15 par 24.","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"Lundi : **autoritaire**. Mardi : on consulte puis on décide seul, **consultatif**. Mercredi : **participatif**. Jeudi : décision seule mais attentionnée, **paternaliste**."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Le **mercredi**, l’équipe vote avec le directeur : c’est le style participatif."},{"cle":{"type":"nombre","valeur":62.5,"tolerance":0.05},"affichage":"62,5 %","explication":"15 ÷ 24 = 0,625, soit **62,5 %**."}]$ex$::jsonb),
  ('68a546b8-1543-5849-875a-2e2933b8756b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Pourquoi les développeurs restent-ils ?","competence":"lire-graphique","situation":"Une entreprise de logiciels imaginaire a interrogé ses 200 développeurs : qu’est-ce qui leur donne le plus envie de rester ? Chacun a cité un seul facteur.","documents":[{"id":"enquete","type":"graphique","forme":"barres-h","titre":"Facteur de motivation cité en premier (200 réponses)","source":"Chiffres imaginés pour l’exercice.","categories":["Intérêt du travail","Salaire","Besoin d’accomplissement","Reconnaissance","Conditions de travail"],"series":[{"nom":"Réponses","valeurs":[70,50,40,25,15],"teinte":"violet"}],"axeY":{"titre":"Nombre de réponses","min":0,"max":80,"pas":20}}],"questions":[{"enonce":"Touche le facteur le plus souvent cité.","aide":"Cherche la barre la plus longue.","type":"zone","document":"enquete","multiple":false},{"enonce":"Range chaque facteur dans la bonne colonne.","aide":"Interne : il vient du travail et de la personne. Externe : il vient de l’extérieur.","type":"categories","categories":[{"id":"c0","texte":"Facteur interne"},{"id":"c1","texte":"Facteur externe"}],"items":[{"id":"i0","texte":"Salaire"},{"id":"i1","texte":"Conditions de travail"},{"id":"i2","texte":"Reconnaissance"},{"id":"i3","texte":"Besoin d’accomplissement"},{"id":"i4","texte":"Intérêt du travail"}]},{"enonce":"Quelle part des réponses concerne des facteurs internes ?","aide":"Additionne les deux facteurs internes, puis divise par 200.","type":"nombre","unite":"%"},{"enonce":"Quelle mesure répond au facteur le plus cité ?","aide":"Quel levier agit sur l’intérêt du travail lui-même ?","type":"choix","options":[{"id":"a","texte":"Rénover les locaux et remplacer les fauteuils pour améliorer leurs conditions de travail"},{"id":"b","texte":"Augmenter tous les salaires de 2 % et ne rien changer d’autre à leur quotidien"},{"id":"c","texte":"Confier aux développeurs le choix de leurs projets et enrichir le contenu de leur travail"},{"id":"d","texte":"Envoyer un message de félicitations à l’ensemble des équipes à chaque fin d’année"}],"multiple":false}]}$ex$::jsonb,
