  ('68a546b8-1543-5849-875a-2e2933b8756b'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Dividendes ou salaires ?","competence":"raisonner","situation":"Une entreprise imaginaire a dégagé 500 000 € de bénéfice. Elle compte 2 000 actions et 50 salariés. La direction hésite entre deux répartitions.","documents":[{"id":"attentes","type":"tableau","titre":"Ce que chacun attend","source":"Attentes simplifiées, imaginées pour l’exercice.","colonnes":["Acteur","Attente principale"],"lignes":[["Salariés","Une rémunération qui progresse et un emploi sûr"],["Actionnaires","Des dividendes et des titres qui prennent de la valeur"],["Dirigeants","Réussir et être reconnus pour leurs résultats"]],"enteteLignes":true},{"id":"options","type":"tableau","titre":"Deux répartitions possibles","source":"Chiffres imaginés pour l’exercice.","colonnes":["","Option A","Option B"],"lignes":[["Dividendes versés","400 000 €","250 000 €"],["Augmentations de salaires","100 000 €","250 000 €"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’acteur qui attend avant tout des dividendes.","aide":"Les dividendes rémunèrent les titres détenus.","type":"zone","document":"attentes","multiple":false},{"enonce":"Quel dividende chaque action reçoit-elle avec l’option B, en euros ?","aide":"Divise les dividendes de l’option B par le nombre d’actions.","type":"nombre","unite":"€"},{"enonce":"Avec l’option B plutôt que A, de combien l’augmentation moyenne par salarié est-elle supérieure, en euros ?","aide":"Calcule l’augmentation moyenne par salarié pour chaque option.","type":"nombre","unite":"€"},{"enonce":"Comment le management peut-il fédérer les deux groupes ?","aide":"Les intérêts divergent : il faut un dispositif qui les rapproche.","type":"choix","options":[{"id":"a","texte":"Présenter aux deux groupes un compromis, avec un intéressement des salariés aux résultats"},{"id":"b","texte":"Verser tout le bénéfice aux actionnaires, puisque les salariés sont déjà payés par leur salaire"},{"id":"c","texte":"Verser tout le bénéfice aux salariés, puisque les actionnaires n’ont aucun rôle dans l’entreprise"},{"id":"d","texte":"Décider seul sans en parler, car les intérêts des deux groupes sont forcément identiques"}],"multiple":false}]}$ex$::jsonb,
