   $ex${"titre":"Le casque de Léa","competence":"analyser-document","situation":"Léa doit remplacer son casque audio. Elle raconte son achat à Noah, par messages.","documents":[{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Noah","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"Mon casque est mort, il m’en faut un nouveau."},{"qui":"Léa","texte":"J’ai comparé trois sites et lu les avis des clients."},{"qui":"Noah","texte":"Tu prends lequel ?"},{"qui":"Léa","texte":"Celui à 89 €. Sur l’autre site, il coûte 94 € + 4,90 € de livraison."},{"qui":"Léa","texte":"Je l’ai commandé ! Je mettrai cinq étoiles s’il est bon."},{"qui":"Noah","texte":"Moi j’ai le même : tout le monde en a un dans ma classe."}]}],"questions":[{"enonce":"Associe chaque message de Léa à l’étape du processus d’achat.","aide":"Suis l’ordre des messages.","type":"association","gauche":[{"id":"g0","texte":"« Mon casque est mort »"},{"id":"g1","texte":"« J’ai comparé trois sites »"},{"id":"g2","texte":"« Je l’ai commandé ! »"},{"id":"g3","texte":"« Je mettrai cinq étoiles »"}],"droite":[{"id":"d0","texte":"Prise de conscience du besoin"},{"id":"d1","texte":"Recherche d’informations"},{"id":"d2","texte":"Comportement après l’achat"},{"id":"d3","texte":"Décision d’achat"}]},{"enonce":"Combien Léa aurait-elle payé de plus sur l’autre site, livraison comprise, en euros ?","aide":"Additionne le prix et la livraison de l’autre site, puis retranche 89 €.","type":"nombre","unite":"€"},{"enonce":"Pourquoi Noah achète-t-il le même casque ?","aide":"Relis le dernier message de Noah.","type":"choix","options":[{"id":"a","texte":"Un frein : une force qui retient l’acheteur avant qu’il se décide"},{"id":"b","texte":"Un besoin physiologique : la sensation de manque d’un objet vital"},{"id":"c","texte":"Un facteur social : l’influence du groupe de camarades sur ses choix"},{"id":"d","texte":"Une attitude défavorable envers la marque du casque