  ('f372e048-2b4a-5b3d-9f53-4177fe14429f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Quand l’affiche ne suffit plus","competence":"raisonner","situation":"Le Bistrot Soleil, chaîne imaginaire de six restaurants, a lancé une campagne sur ses produits locaux. Sa note moyenne en ligne et un article permettent de comprendre ce qui s’est passé.","documents":[{"id":"notes","type":"graphique","forme":"courbe","titre":"Note moyenne des avis en ligne","source":"Chiffres imaginés pour l’exercice.","categories":["Janv.","Févr.","Mars","Avr.","Mai","Juin"],"series":[{"nom":"Note","valeurs":[4.5,4.5,4.4,3.6,3.4,3.7],"teinte":"violet"}],"axeY":{"titre":"Note moyenne","unite":"sur 5","min":3,"max":5,"pas":0.5},"axeX":{"titre":"Mois"}},{"id":"article","type":"texte","genre":"article","titre":"Le Bistrot Soleil sous le feu des critiques","source":"Article imaginé pour l’exercice.","blocs":["En mars, le Bistrot Soleil lance une grande campagne d’affichage : « Cuisine 100 % locale, de la ferme à l’assiette ».","Début avril, un ancien cuisinier explique sur un réseau social que l’essentiel des produits vient d’un grossiste national.","Les avis négatifs se multiplient en ligne ; la direction ne répond d’abord à aucun commentaire."]}],"questions":[{"enonce":"Touche le mois où la note moyenne chute le plus fortement.","aide":"Cherche la plus grande descente entre deux mois voisins.","type":"zone","document":"notes","multiple":false},{"enonce":"De combien la note a-t-elle baissé entre mars et avril ?","aide":"Soustrais la note d’avril à celle de mars.","type":"nombre","unite":"point"},{"enonce":"Comment qualifier la campagne d’affichage de mars ?","aide":"Elle met en avant des valeurs, pas un produit précis.","type":"choix","options":[{"id":"a","texte":"Une communication interne descendante : elle s’adresse uniquement aux salariés"},{"id":"b","texte":"Une communication financière : elle informe les banques sur la solvabilité"},{"id":"c","texte":"Une communication institutionnelle : elle valorise l’image de l’entreprise sans vendre un plat"},{"id":"d","texte":"Une communication ascendante : elle fait remonter les idées des clients"}],"multiple":false},{"enonce":"De combien la note a-t-elle remonté entre mai et juin ?","aide":"Soustrais la note de mai à celle de juin.","type":"nombre","unite":"point"},{"enonce":"Quelle leçon l’entreprise doit-elle en tirer ?","aide":"Un salarié a contredit le message de la campagne.","type":"choix","options":[{"id":"a","texte":"L’e-réputation d’une entreprise dépend uniquement de la publicité qu’elle choisit de diffuser"},{"id":"b","texte":"Les salariés ne font pas partie des acteurs dont l’entreprise doit tenir compte en ligne"},{"id":"c","texte":"Il faut communiquer davantage à l’extérieur pour couvrir les avis négatifs publiés en ligne"},{"id":"d","texte":"Ce qui est dit à l’extérieur doit être vrai à l’intérieur : le discours doit rester cohérent"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"La note tombe en **avril**, juste après les révélations sur l’origine des produits."},{"cle":{"type":"nombre","valeur":0.8,"tolerance":0.01},"affichage":"0,8 point","explication":"4,4 − 3,6 = **0,8 point**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Elle vante l’engagement « local » de l’entreprise : c’est une communication **institutionnelle**."},{"cle":{"type":"nombre","valeur":0.3,"tolerance":0.01},"affichage":"0,3 point","explication":"3,7 − 3,4 = **0,3 point**, une remontée encore loin des 4,4 de mars."},{"cle":{"type":"choix","ids":["d"]},"explication":"La **communication globale** harmonise interne et externe : un décalage entre discours et réalité se paie cher en ligne."}]$ex$::jsonb),
  ('d1a45a7f-0049-5e74-90af-091ce2dc2a24'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La lessive « 100 % naturelle »","competence":"analyser-document","situation":"FleurVerte est une marque de lessive imaginaire. Son affiche vante ses engagements ; le tableau donne la composition réelle d’un flacon de 1 000 g.","documents":[{"id":"aff","type":"fiche","modele":"affiche","entete":"Lessive FleurVerte","sousTitre":"Notre engagement pour la planète","emoji":"🌿","lignes":[{"texte":"Formule 100 % naturelle","id":"z1"},{"texte":"Flacon en plastique recyclé à 30 %","id":"z2"},{"texte":"Fabriquée avec soin","id":"z3"}],"source":"Affiche imaginée pour l’exercice."},{"id":"compo","type":"tableau","titre":"Composition d’un flacon","colonnes":["Élément","Mesure"],"lignes":[["Ingrédients d’origine végétale","350 g"],["Ingrédients de synthèse","650 g"],["Plastique recyclé dans le flacon","30 %"]],"enteteLignes":true,"source":"Chiffres imaginés pour l’exercice."}],"questions":[{"enonce":"Touche l’affirmation de l’affiche que contredit le tableau de composition.","aide":"Compare chaque phrase de l’affiche avec les chiffres du tableau.","type":"zone","document":"aff","multiple":false},{"enonce":"Un flacon contient 1 000 g de lessive. Quel pourcentage des ingrédients est d’origine synthétique ?","aide":"Divise les grammes de synthèse par 1 000, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Associe chaque partie prenante au préjudice qu’elle subit à cause de cette affiche.","aide":"Demande-toi ce que chacun perd quand une promesse est fausse.","type":"association","gauche":[{"id":"g0","texte":"Clients"},{"id":"g1","texte":"Concurrents honnêtes"},{"id":"g2","texte":"Salariés de la marque"}],"droite":[{"id":"d0","texte":"Voient leur emploi menacé si la confiance disparaît"},{"id":"d1","texte":"Perdent des ventes face à une promesse fausse"},{"id":"d2","texte":"Sont trompés sur ce qu’ils achètent"}]}]}$ex$::jsonb,
