  ('d1a45a7f-0049-5e74-90af-091ce2dc2a24'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"L’index d’Alpha Logistique","competence":"analyser-document","situation":"Alpha Logistique, entreprise imaginaire de 300 salariés, publie son index de l’égalité professionnelle entre les femmes et les hommes. Il est noté sur 100 points.","documents":[{"id":"index","type":"tableau","titre":"Les cinq indicateurs de l’index","colonnes":["Indicateur","Points obtenus","Maximum"],"lignes":[["Écart de rémunération entre femmes et hommes",28,40],["Écart de taux d’augmentations individuelles",20,20],["Écart de taux de promotions",8,15],["Augmentations au retour d’un congé de maternité",15,15],["Femmes parmi les dix plus hautes rémunérations",0,10]],"enteteLignes":true,"source":"Chiffres imaginés pour l’exercice."},{"id":"regle","type":"texte","genre":"consigne","titre":"La règle","blocs":["Une entreprise d’au moins 50 salariés publie son index chaque année. Sous 75 points sur 100, elle doit adopter des mesures correctrices, sous peine de pénalité financière."],"source":"Règle résumée pour l’exercice."}],"questions":[{"enonce":"Touche l’indicateur sur lequel Alpha Logistique perd le plus de points par rapport au maximum.","aide":"Pour chaque ligne, calcule maximum moins points obtenus.","type":"zone","document":"index","multiple":false},{"enonce":"Quel est l’index d’Alpha Logistique, c’est-à-dire le total des points obtenus ?","aide":"Additionne la colonne « Points obtenus ».","type":"nombre","unite":"points"},{"enonce":"Que doit faire Alpha Logistique au vu de son index ?","aide":"Compare l’index au seuil donné dans le document « La règle ».","type":"choix","options":[{"id":"a","texte":"Adopter des mesures correctrices, car 71 points est en dessous du seuil de 75"},{"id":"b","texte":"Attendre la prochaine année, car le seuil ne s’applique qu’au-delà de 500 salariés"},{"id":"c","texte":"Ne rien changer, car 71 points dépasse la moyenne de 50 points sur 100"},{"id":"d","texte":"Cacher son index, car seules les entreprises de moins de 50 salariés le publient"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0"]},"explication":"La perte est de 12 points pour la rémunération, contre 7 pour les promotions et 10 pour les hautes rémunérations : c’est l’**écart de rémunération** qui pèse le plus."},{"cle":{"type":"nombre","valeur":71,"tolerance":0},"affichage":"71 points","explication":"28 + 20 + 8 + 15 + 0 = **71 points** sur 100."},{"cle":{"type":"choix","ids":["a"]},"explication":"71 < 75 : l’entreprise doit adopter des **mesures correctrices**, sous peine de pénalité. L’index se publie dès 50 salariés."}]$ex$::jsonb),
  ('d1a45a7f-0049-5e74-90af-091ce2dc2a24'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Polybat : des comptes trop beaux","competence":"analyser-texte","situation":"Polybat, entreprise imaginaire du bâtiment, publie des comptes flatteurs. Son commissaire aux comptes refuse pourtant de les certifier. À toi de comprendre pourquoi.","documents":[{"id":"art","type":"texte","genre":"article","titre":"Le commissaire aux comptes dit non","blocs":["Le commissaire aux comptes de Polybat a refusé de certifier les comptes de l’exercice. Dans son rapport, il relève que des matériaux invendables sont restés dans les stocks à leur prix d’achat, alors qu’ils auraient dû être dépréciés.","La direction espérait ainsi annoncer un bénéfice de 2,5 millions d’euros. Les matériaux concernés figurent au bilan pour 9 millions d’euros, mais leur valeur réelle n’atteint que 5 millions.","Les actionnaires, la banque qui finance l’entreprise et les salariés, dont la prime dépend du résultat, avaient fondé leurs décisions sur ces chiffres."],"source":"Article imaginé pour l’exercice."},{"id":"chiffres","type":"tableau","titre":"Les chiffres en jeu","colonnes":["Élément","Montant (M€)"],"lignes":[["Résultat annoncé","2,5"],["Valeur des matériaux au bilan","9"],["Valeur réelle des matériaux","5"]],"enteteLignes":true,"source":"Chiffres imaginés pour l’exercice."}],"questions":[{"enonce":"Touche le mot qui dit ce qu’aurait dû subir la valeur des matériaux invendables.","aide":"Cherche le verbe qui décrit une baisse de valeur comptable.","type":"zone","document":"art","multiple":false},{"enonce":"De combien de millions d’euros les matériaux sont-ils surévalués au bilan ?","aide":"Compare la valeur au bilan et la valeur réelle.","type":"nombre","unite":"M€"},{"enonce":"En corrigeant cette erreur, quelle perte Polybat aurait-elle dû annoncer, en millions d’euros ?","aide":"Retranche la surévaluation du résultat annoncé : le résultat devient négatif.","type":"nombre","unite":"M€"},{"enonce":"Quel principe comptable Polybat a-t-elle violé en gardant ces matériaux à leur prix d’achat ?","aide":"Un principe demande d’anticiper les pertes probables sans anticiper les gains.","type":"choix","options":[{"id":"a","texte":"L’indépendance des exercices : les charges se rattachent à la bonne année"},{"id":"b","texte":"La prudence : les pertes probables doivent être anticipées"},{"id":"c","texte":"La permanence des méthodes : on ne change pas de méthode d’un exercice à l’autre"},{"id":"d","texte":"La continuité de l’exploitation : l’entreprise est supposée poursuivre son activité"}],"multiple":false},{"enonce":"Associe chaque partie prenante au risque qu’elle court à cause de ces comptes truqués.","aide":"Pense à ce que chacun fait à partir du résultat annoncé.","type":"association","gauche":[{"id":"g0","texte":"Actionnaires"},{"id":"g1","texte":"Banque prêteuse"},{"id":"g2","texte":"Salariés"}],"droite":[{"id":"d0","texte":"Toucher une prime calculée sur un bénéfice fictif"},{"id":"d1","texte":"Acheter des titres à un prix gonflé"},{"id":"d2","texte":"Prêter à une entreprise en réalité déficitaire"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m40"]},"explication":"Les matériaux auraient dû être **dépréciés** : leur valeur au bilan devait baisser pour refléter leur valeur réelle."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 M€","explication":"9 − 5 = **4 millions d’euros** de surévaluation."},{"cle":{"type":"nombre","valeur":1.5,"tolerance":0},"affichage":"1,5 M€","explication":"2,5 − 4 = −1,5 : Polybat aurait dû annoncer une **perte de 1,5 million d’euros**, et non un bénéfice."},{"cle":{"type":"choix","ids":["b"]},"explication":"Ne pas déprécier des stocks invendables, c’est ignorer une perte probable : c’est contraire au principe de **prudence**."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Des comptes truqués **trompent les actionnaires, les prêteurs et les salariés** : tous décident à partir de chiffres faux."}]$ex$::jsonb),
  ('3a60e7b4-021b-5709-96b1-d4f5df521f4c'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Combien de jours à la maison ?","competence":"lire-graphique","situation":"L’entreprise imaginaire Kalys a interrogé ses 220 salariés : combien de jours par semaine souhaitent-ils télétravailler ?","documents":[{"id":"enq","type":"graphique","forme":"barres","titre":"Jours de télétravail souhaités par semaine","categories":["0 jour","1 jour","2 jours","3 jours","4 jours ou plus"],"series":[{"nom":"Salariés","valeurs":[20,35,90,55,20],"teinte":"violet"}],"axeY":{"titre":"Salariés","min":0,"max":100,"pas":20},"axeX":{"titre":"Jours souhaités"},"valeurs":false,"source":"Enquête imaginée pour l’exercice."}],"questions":[{"enonce":"Touche la réponse choisie par le plus grand nombre de salariés.","aide":"Cherche la barre la plus haute.","type":"zone","document":"enq","multiple":false},{"enonce":"Quel pourcentage des 220 salariés souhaite télétravailler au moins 2 jours par semaine ?","aide":"Additionne les barres « 2 jours », « 3 jours » et « 4 jours ou plus », puis divise par 220.","type":"nombre","unite":"%"},{"enonce":"Associe chaque évolution du rapport au travail à une réponse possible de Kalys.","aide":"Relie le temps, le lieu et la vie connectée à leur réponse.","type":"association","gauche":[{"id":"g0","texte":"Envie d’équilibre entre vie privée et vie professionnelle"},{"id":"g1","texte":"Essor du télétravail"},{"id":"g2","texte":"Sollicitations permanentes en ligne"}],"droite":[{"id":"d0","texte":"Accord de télétravail et équipements"},{"id":"d1","texte":"Horaires flexibles"},{"id":"d2","texte":"Droit à la déconnexion"}]}]}$ex$::jsonb,
