  ('3a60e7b4-021b-5709-96b1-d4f5df521f4c'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les conditions de VitaPas","competence":"analyser-document","situation":"VitaPas, application imaginaire de santé connectée, ne sert qu’à compter les pas de ses utilisateurs. Voici ses conditions d’utilisation et quelques chiffres sur le groupe qui l’édite.","documents":[{"id":"cgu","type":"fiche","modele":"affiche","entete":"VitaPas","sousTitre":"Conditions d’utilisation","emoji":"📱","lignes":[{"texte":"Nous collectons vos pas, votre rythme cardiaque et votre sommeil.","id":"z1"},{"texte":"Vos données peuvent être transmises à nos partenaires publicitaires.","id":"z2"},{"texte":"En ouvrant l’application, vous acceptez automatiquement ces conditions.","id":"z3"},{"texte":"Pour supprimer votre compte, écrivez-nous par courrier recommandé.","id":"z4"}],"source":"Conditions imaginées pour l’exercice."},{"id":"groupe","type":"tableau","titre":"Le groupe VitaPas","colonnes":["Élément","Valeur"],"lignes":[["Chiffre d’affaires mondial","2 000 M€"],["Utilisateurs de l’application","3 millions"],["Plafond de l’amende RGPD","4 % du chiffre d’affaires mondial"]],"enteteLignes":true,"source":"Chiffres imaginés pour l’exercice."}],"questions":[{"enonce":"Touche la clause qui ne respecte pas l’exigence de consentement.","aide":"Le consentement doit être libre et explicite : un simple usage suffit-il ?","type":"zone","document":"cgu","multiple":false},{"enonce":"Associe chaque clause à l’obligation du RGPD qu’elle ne respecte pas.","aide":"L’application ne sert qu’à compter les pas : qu’est-ce qui dépasse ce but ?","type":"association","gauche":[{"id":"g0","texte":"Collecter le sommeil et le rythme cardiaque"},{"id":"g1","texte":"Transmettre aux partenaires publicitaires"},{"id":"g2","texte":"Accepter automatiquement"},{"id":"g3","texte":"Supprimer par courrier recommandé"}],"droite":[{"id":"d0","texte":"Consentement : un accord libre et explicite"},{"id":"d1","texte":"Finalité : un usage annoncé et précis"},{"id":"d2","texte":"Minimisation : seulement les données utiles"},{"id":"d3","texte":"Droits des personnes : les exercer facilement"}]},{"enonce":"Quel est le montant maximal de l’amende, en millions d’euros, pour ce groupe ?","aide":"Calcule 4 % du chiffre d’affaires mondial.","type":"nombre","unite":"M€"},{"enonce":"Complète la phrase.","aide":"Une donnée de santé touche à l’intimité de la personne.","type":"trous","segments":["Le rythme cardiaque et le sommeil sont des données de santé : ce sont des données ",0," qui exigent un consentement ",1," et une sécurité renforcée."],"banque":["explicite","ouvertes","sensibles","implicite"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Accepter « automatiquement » n’est pas un consentement : il doit être **libre et explicite**."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"Le **sommeil** dépasse le besoin (minimisation), la **publicité** détourne le but annoncé (finalité), l’**acceptation automatique** n’est pas un consentement et le **courrier recommandé** freine l’exercice des droits."},{"cle":{"type":"nombre","valeur":80,"tolerance":0},"affichage":"80 M€","explication":"4 % de 2 000 M€ = 2 000 × 0,04 = **80 M€**."},{"cle":{"type":"trous","trous":[["sensibles"],["explicite"]]},"affichage":"sensibles · explicite","explication":"Les données de santé sont des données **sensibles** : elles exigent un consentement **explicite** et une sécurité renforcée."}]$ex$::jsonb),
  ('3a60e7b4-021b-5709-96b1-d4f5df521f4c'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une place en crèche décidée par un algorithme","competence":"analyser-document","situation":"La mairie imaginaire de Valbourg attribue l’unique place de sa crèche grâce à un algorithme. Quatre familles ont déposé un dossier.","documents":[{"id":"regles","type":"texte","genre":"consigne","titre":"Les règles de l’algorithme","blocs":["Chaque famille reçoit un score : 3 points par parent qui travaille, 2 points si un enfant de la famille fréquente déjà la crèche, 4 points si elle habite la commune, 1 point si ses revenus sont inférieurs à 25 000 € par an.","La famille qui a le score le plus élevé obtient la place."],"source":"Règles imaginées pour l’exercice."},{"id":"fam","type":"tableau","titre":"Les dossiers reçus","colonnes":["Famille","Parents qui travaillent","Enfant déjà accueilli","Habite la commune","Revenus < 25 000 €"],"lignes":[["A",2,"Oui","Oui","Non"],["B",1,"Oui","Oui","Non"],["C",2,"Non","Non","Oui"],["D",2,"Oui","Non","Non"]],"enteteLignes":true,"source":"Chiffres imaginés pour l’exercice."}],"questions":[{"enonce":"Quel est le score de la famille D ?","aide":"Applique chaque règle : 3 points par parent qui travaille, puis les autres critères qui valent « Oui ».","type":"nombre","unite":"points"},{"enonce":"Touche la famille qui obtient la place.","aide":"Calcule le score de chaque famille, puis garde le plus élevé.","type":"zone","document":"fam","multiple":false},{"enonce":"De combien de points la famille A devance-t-elle la deuxième famille ?","aide":"Repère la deuxième meilleure famille, puis fais la différence.","type":"nombre","unite":"points"},{"enonce":"La famille C demande pourquoi sa demande a été refusée. Que doit faire la mairie ?","aide":"Une décision individuelle prise par algorithme doit pouvoir s’expliquer à la personne concernée.","type":"choix","options":[{"id":"a","texte":"Lui répondre que les règles de l’algorithme sont confidentielles et ne s’expliquent pas"},{"id":"b","texte":"Lui dire qu’un algorithme a été utilisé et lui expliquer les règles de calcul du score"},{"id":"c","texte":"Lui envoyer la liste des scores de toutes les autres familles avec leurs noms"},{"id":"d","texte":"Lui proposer de recalculer son score à la main sans lui donner les critères"}],"multiple":false}]}$ex$::jsonb,
