aux d’intérêt.","type":"choix","options":[{"id":"a","texte":"L’emprunt fait baisser la rentabilité économique de 10 % à 4 %"},{"id":"b","texte":"L’effet de levier est défavorable : chaque euro emprunté fait perdre de l’argent"},{"id":"c","texte":"L’effet de levier est favorable : l’emprunt peut augmenter la rentabilité financière"},{"id":"d","texte":"Il n’y a pas d’effet de levier, puisque l’entreprise est déjà rentable"}],"multiple":false}]}$ex$::jsonb,
